node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ':', cols.map(c => c.name).join(', '));
  const count = db.prepare('SELECT COUNT(*) as cnt FROM ' + t.name).get();
  console.log('  rows:', count.cnt);
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Search for the products by ID
const ids = ['PROD-FA0948', 'PROD-2DBA15', 'PROD-7C0240'];
for (const id of ids) {
  const row = db.prepare('SELECT * FROM products WHERE product_id = ?').get(id);
  if (row) {
    console.log('=== FOUND:', id, '===');
    console.log(JSON.stringify(row, null, 2));
  } else {
    console.log('NOT FOUND:', id);
  }
}

// Also search by partial match or name containing 'mouse' or 'wireless'
console.log('\n=== All products with mouse/wireless in name ===');
const mice = db.prepare(\"SELECT product_id, name, category, brand, price, current_price, in_stock, stock_quantity, rating, review_count, description FROM products WHERE LOWER(name) LIKE '%mouse%' OR LOWER(name) LIKE '%wireless%' OR LOWER(category) LIKE '%mouse%'\").all();
console.log(JSON.stringify(mice, null, 2));
"

